<script setup lang="ts">
import { money, totals } from '~/utils/quotes'
const route = useRoute()
const { data, error, refresh } = await useFetch<any>(`/api/public/${encodeURIComponent(String(route.params.token))}`)
const name = ref(''), confirmed = ref(false), busy = ref(false), feedback = ref(''), decision = ref('Accepted')
const snapshot = computed(() => data.value?.snapshot)
const amounts = computed(() => snapshot.value ? totals(snapshot.value.quote.items, snapshot.value.quote.discount, snapshot.value.quote.tax) : null)
async function respond() {
  busy.value = true; feedback.value = ''
  try { await $fetch(`/api/public/${encodeURIComponent(String(route.params.token))}`, { method: 'POST', body: { decision: decision.value, name: name.value, confirmed: confirmed.value } }); await refresh(); feedback.value = 'Your response has been recorded. Thank you.' }
  catch (e: any) { feedback.value = e.data?.statusMessage || 'Unable to record your response. Please try again.'; await refresh() }
  finally { busy.value = false }
}
function print() { window.print() }
useHead({ title: 'Your quotation · QuoteFollow PH', meta: [{ name: 'robots', content: 'noindex, nofollow' }, { name: 'referrer', content: 'no-referrer' }] })
</script>
<template><main class="public-quote"><section v-if="error || !snapshot" class="panel auth-card"><h1>Quote unavailable</h1><p>This link may have been revoked or is unavailable. Please contact the business for a new link.</p></section><section v-else class="panel public-document"><header class="print-business"><span class="brand-mark"><AppIcon name="check" /></span><div><h2>{{ snapshot.business.name }}</h2><p>{{ snapshot.business.address }}</p><p>{{ snapshot.business.email }} {{ snapshot.business.phone }}</p></div><span :class="['badge', data.status.toLowerCase() ]">{{ data.status }}</span></header><div class="preview-meta"><div><small>PREPARED FOR</small><strong>{{ snapshot.customer.name }}</strong><p>{{ snapshot.customer.company }}</p><p>{{ snapshot.customer.address }}</p></div><div><small>{{ snapshot.quote.id }}</small><h1>{{ snapshot.quote.title }}</h1><p>Valid until {{ snapshot.quote.expires }} · Philippine time</p></div></div><div class="table-scroll"><table class="preview-table"><thead><tr><th>SERVICE</th><th>QTY</th><th>RATE</th><th>AMOUNT</th></tr></thead><tbody><tr v-for="(item,i) in snapshot.quote.items" :key="i"><td>{{ item.name }}</td><td>{{ item.quantity }}</td><td>{{ money(item.price) }}</td><td>{{ money(Math.round(item.price * item.quantity)) }}</td></tr></tbody></table></div><div v-if="amounts" class="preview-totals"><p><span>Subtotal</span>{{ money(amounts.subtotal) }}</p><p><span>Discount</span>−{{ money(amounts.discount) }}</p><p><span>Tax</span>{{ money(amounts.taxAmount) }}</p><div class="quote-total"><span>Total estimate</span><strong>{{ money(amounts.total) }}</strong></div></div><div class="preview-notes"><h3>Notes & inclusions</h3><p>{{ snapshot.quote.notes || 'Contact the business if you need further details.' }}</p><h3 v-if="snapshot.business.terms">Terms</h3><p>{{ snapshot.business.terms }}</p></div><section class="customer-response"><h2>{{ data.status === 'Sent' ? 'Your response' : `Quote ${data.status.toLowerCase()}` }}</h2><p v-if="data.respondedAt">Recorded for {{ data.responderName }} on {{ new Date(data.respondedAt).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }) }} (Philippine time).</p><form v-if="data.status === 'Sent'" @submit.prevent="respond"><label>Your name<input v-model="name" autocomplete="name" minlength="2" maxlength="100" required></label><label>Decision<select v-model="decision"><option value="Accepted">Accept this quote</option><option value="Declined">Decline this quote</option></select></label><label class="checkbox-label"><input v-model="confirmed" type="checkbox" required>I have reviewed this quote and confirm my decision.</label><UiButton type="submit" :disabled="busy || !confirmed">{{ busy ? 'Recording…' : 'Confirm response' }}</UiButton></form><p v-if="feedback" class="notice" role="status">{{ feedback }}</p><UiButton variant="outline" @click="print">Print / Save PDF</UiButton><p class="helper">If you are not the intended recipient, contact the business. Do not forward this private link.</p></section></section></main></template>
